-- c006-v052: לֹא כִּי הֵבִינוּ עַל –הַ לֶחֶם אֲבָל הָיָה שֶׁלָּהֶם הַ לֵב מֻקְשֶׁה
-- c006-v053: וְ עָבְרוּ אֶל –הַ אֶרֶץ בָּאוּ אֶל גִּנֵּיסָר וְ עָגְנוּ
-- c006-v054: וְ יָצְאוּ הֵם מִן –הַ סִירָה מִיָּד הִכִּירוּ אוֹתוֹ
-- c006-v055: רָצוּ כָּל –הַ אֶרֶץ הַהִיא וְ הֵחֵלּוּ עַל –הַ מִטּוֹת –הַ חוֹלִים הָיָה–לָהֶם לְסַבֵּב בְּכָל–מָקוֹם–אֲשֶׁר שָׁמְעוּ כִּי הוּא
-- c006-v056: וְ בְּכָל–מָקוֹם–אֲשֶׁר – נִכְנַס אֶל כְּפָרִים אוֹ אֶל עָרִים אוֹ אֶל שָׂדוֹת בְּ –הַ שְׁוָקִים הֵנִיחוּ –הַ חוֹלִים וְ הִתְחַנְּנוּ אֵלָיו שֶׁ רַק –הַ כָּנָף –הַ בֶּגֶד שֶׁלּוֹ יִגְּעוּ וְ כָּל–אֲשֶׁר – נָגְעוּ בּוֹ נוֹשְׁעוּ

